function load_share(b){var a="includes/share.php";return $.ajax({type:"GET",url:a,data:{component:component,share_pt_text:share_pt_text,share_fb_text:share_fb_text,share_fb_href:share_fb_href,share_tw_text:share_tw_text,share_em_text:share_em_text,share_url:share_url,share_image:share_image},cache:true,success:function(d){$("#share-this").append(d);ZeroClipboard.setMoviePath("./js/zeroclipboard/ZeroClipboard.swf");var c=new ZeroClipboard.Client();c.addEventListener("mousedown",function(){var f="";if(typeof b!=="undefined"){f="&date="+b}var g="&popclk="+(Math.floor(Math.random()*900000)+100000);c.setText('<iframe src="'+_URL_+"embed.php?component="+component+f+g+'" width="389" height="'+($("#main-wrapper").outerHeight()+16)+'" frameBorder="0" allowtransparency="true"></iframe>')});var e=$("div#copy-notice");c.addEventListener("complete",function(g,f){e.css({opacity:1});e.animate({opacity:0},1000)});c.glue("embed-this")}})}function download_csv(b,a){$('<div style="display:none"><form action="share/jsontocsv.php" method="post" target="_blank"><input name="json" /><input name="component" /></form></div>').appendTo("body").find('input[name="json"]').val(JSON.stringify(b)).end().find('input[name="component"]').val(a).end().find("form").submit().end().remove()}function image_url(a){return _URL_+"share/images/"+image_name(a)}function image_name(a){return a+".png"}function find_image(b){var a=image_url(b);return $.ajax({type:"GET",url:a,cache:false})}function create_image(a,c){var b="share/svgtoimage.php";return $.ajax({type:"POST",url:b,data:{svg:a,name:image_name(c)}})};